/* Shared drawing for C modules: filled rectangles and 5x7 text (font.h,
 * generated by font5x7.py), streamed in 128-byte big-endian RGB565 writes. */
#include "h9mod.h"
#include "gfx.h"
#include "font.h"

void gfx_fill(unsigned x, unsigned y, unsigned w, unsigned h, uint16_t color)
{
    uint8_t buffer[128];
    if (!w || !h) return;
    for (unsigned i = 0; i < sizeof buffer; i += 2) {
        buffer[i] = (uint8_t)(color >> 8);
        buffer[i + 1] = (uint8_t)color;
    }
    h9_lcd_window(x, y, x + w - 1, y + h - 1);
    for (unsigned left = w * h * 2; left;) {
        unsigned n = left < sizeof buffer ? left : sizeof buffer;
        h9_lcd_write(buffer, n);
        left -= n;
    }
}

static const uint8_t *glyph(char c)
{
    if (c >= 'a' && c <= 'z') c = (char)(c - 32);
    for (unsigned i = 0; FONT_CHARS[i]; i++)
        if (FONT_CHARS[i] == c) return FONT[i];
    return FONT[0]; /* blank */
}

/* One character cell of 6x8 pixels at `scale`, streamed row by row. */
static void draw_char(unsigned x, unsigned y, char c, unsigned scale, uint16_t fg, uint16_t bg)
{
    const uint8_t *rows = glyph(c);
    uint8_t buffer[128];
    unsigned used = 0, w = 6 * scale, h = 8 * scale;
    h9_lcd_window(x, y, x + w - 1, y + h - 1);
    for (unsigned py = 0; py < h; py++) {
        unsigned row = py / scale;
        unsigned bits = row < 7 ? rows[row] : 0;
        for (unsigned px = 0; px < w; px++) {
            unsigned col = px / scale;
            uint16_t color = col < 5 && (bits >> (4 - col)) & 1 ? fg : bg;
            buffer[used++] = (uint8_t)(color >> 8);
            buffer[used++] = (uint8_t)color;
            if (used == sizeof buffer) {
                h9_lcd_write(buffer, used);
                used = 0;
            }
        }
    }
    if (used) h9_lcd_write(buffer, used);
}

unsigned gfx_text(unsigned x, unsigned y, const char *text, unsigned max, unsigned scale, uint16_t fg, uint16_t bg)
{
    for (unsigned i = 0; i < max && text[i]; i++, x += 6 * scale)
        draw_char(x, y, text[i], scale, fg, bg);
    return x;
}

/* Wait until no key is down (the key that started a module may still be held). */
void gfx_wait_release(void)
{
    while (h9_key() != H9_KEY_NONE) h9_delay(2);
}

/* Wait for a new key press; returns its key byte. */
unsigned gfx_wait_key(void)
{
    unsigned last = h9_key();
    for (;;) {
        h9_delay(2);
        unsigned key = h9_key();
        if (key != last && key != H9_KEY_NONE) return key;
        last = key;
    }
}

/* The compiler emits these for struct copies and large zeroing. */
void *memcpy(void *dst, const void *src, unsigned n)
{
    uint8_t *d = dst;
    const uint8_t *s = src;
    while (n--) *d++ = *s++;
    return dst;
}

void *memset(void *dst, int value, unsigned n)
{
    uint8_t *d = dst;
    while (n--) *d++ = (uint8_t)value;
    return dst;
}
